function Logo() {
  return <Link href="/" className="flex items-center gap-3" data-testid="link-logo"><span className="flex h-9 w-9 items-center justify-center rounded-full border border-[#c9a961] text-[17px] font-serif text-[#c9a961]">L</span><span className="font-serif text-xl tracking-[.22em]">LUMEA</span></Link>;
}

function Header({ onMenu }: { onMenu: () => void }) {
  const [, setLocation] = useLocation();
  const [search, setSearch] = useState('');
  const { data: notifications } = useListNotifications();
  const unread = notifications?.filter((item) => !item.isRead).length ?? 0;
  return <header className="sticky top-0 z-40 border-b border-[#d9d0bf] bg-[#f5f0e6]/95 backdrop-blur-md">
    <div className="mx-auto flex h-[72px] max-w-[1320px] items-center gap-5 px-5 lg:px-10">
      <button onClick={onMenu} className="rounded-full p-2 lg:hidden" data-testid="button-open-menu"><Menu size={21} /></button>
      <Logo />
      <nav className="ml-7 hidden items-center gap-7 text-[12px] font-semibold uppercase tracking-[.14em] text-[#6f6b63] lg:flex">
        <Link href="/" className="transition-colors hover:text-[#1a1a1a]" data-testid="link-nav-home">Beranda</Link>
        <Link href="/produk" className="transition-colors hover:text-[#1a1a1a]" data-testid="link-nav-products">Produk</Link>
        <Link href="/pesanan" className="transition-colors hover:text-[#1a1a1a]" data-testid="link-nav-orders">Pesanan</Link>
        <Link href="/seller" className="transition-colors hover:text-[#1a1a1a]" data-testid="link-nav-seller">Untuk penjual</Link>
      </nav>
      <div className="ml-auto flex items-center gap-2">
        <div className="hidden w-52 items-center gap-2 border-b border-[#bdb5a6] px-1 py-2 sm:flex">
          <Search size={17} className="text-[#888176]" />
          <input value={search} onChange={(e) => setSearch(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && setLocation(`/produk?search=${encodeURIComponent(search)}`)} placeholder="Cari sesuatu..." className="w-full bg-transparent text-sm outline-none placeholder:text-[#9b958b]" data-testid="input-header-search" />
        </div>
        <Link href="/notifikasi" className="relative rounded-full p-2.5 hover:bg-[#efe9dc]" data-testid="link-notifications"><Bell size={19} strokeWidth={1.6} />{unread > 0 && <span className="absolute right-1 top-1 flex h-4 min-w-4 items-center justify-center rounded-full bg-[#c9a961] px-1 text-[9px] font-bold">{unread}</span>}</Link>
        <Link href="/keranjang" className="rounded-full p-2.5 hover:bg-[#efe9dc]" data-testid="link-cart"><ShoppingCart size={19} strokeWidth={1.6} /></Link>
        <Link href="/login" className="hidden rounded-full border border-[#c9a961] px-4 py-2 text-[11px] font-bold uppercase tracking-[.12em] sm:block" data-testid="link-login">Masuk</Link>
      </div>
    </div>
  </header>;
}

function BottomNav() {
  return <div className="fixed bottom-0 left-0 right-0 z-40 grid grid-cols-4 border-t border-[#d9d0bf] bg-[#f5f0e6]/95 py-2 backdrop-blur-lg lg:hidden">
    {[[HomeIcon, 'Beranda', '/'], [Search, 'Produk', '/produk'], [ClipboardList, 'Pesanan', '/pesanan'], [UserRound, 'Akun', '/login']].map(([Icon, label, href]) => <Link key={label as string} href={href as string} className="flex flex-col items-center gap-1 py-1 text-[#777168]" data-testid={`link-bottom-${label}`}><Icon size={18} strokeWidth={1.7} /><span className="text-[9px] font-semibold uppercase tracking-[.12em]">{label as string}</span></Link>)}
  </div>;
}

function Shell({ children }: { children: ReactNode }) {
  const [menu, setMenu] = useState(false);
  return <div className="min-h-[100dvh] bg-[#f5f0e6] text-[#1a1a1a]"><Header onMenu={() => setMenu(true)} />{menu && <div className="fixed inset-0 z-50 bg-[#1a1a1a]/20 lg:hidden" onClick={() => setMenu(false)}><aside className="h-full w-[82%] max-w-sm bg-[#f5f0e6] p-6 shadow-2xl" onClick={(e) => e.stopPropagation()}><div className="flex items-center justify-between"><Logo /><button onClick={() => setMenu(false)} data-testid="button-close-menu"><X /></button></div><div className="mt-12 grid gap-5 font-serif text-3xl"><Link href="/" onClick={() => setMenu(false)} data-testid="link-drawer-home">Beranda</Link><Link href="/produk" onClick={() => setMenu(false)} data-testid="link-drawer-products">Produk</Link><Link href="/pesanan" onClick={() => setMenu(false)} data-testid="link-drawer-orders">Pesanan</Link><Link href="/notifikasi" onClick={() => setMenu(false)} data-testid="link-drawer-notifications">Notifikasi</Link><Link href="/seller" onClick={() => setMenu(false)} data-testid="link-drawer-seller">Untuk penjual</Link></div></aside></div>}<main>{children}</main><BottomNav /></div>;
}

function PageIntro({ eyebrow, title, detail }: { eyebrow: string; title: string; detail?: string }) {
  return <div className="mb-9"><p className="mb-3 text-[10px] font-bold uppercase tracking-[.25em] text-[#a3844b]">{eyebrow}</p><h1 className="font-serif text-4xl leading-[1.08] sm:text-5xl">{title}</h1>{detail && <p className="mt-4 max-w-xl text-sm leading-7 text-[#6f6b63]">{detail}</p>}</div>;
}

function LoadingGrid() { return <div className="grid grid-cols-2 gap-x-4 gap-y-8 md:grid-cols-3 lg:grid-cols-4">{Array.from({ length: 8 }).map((_, i) => <div key={i} className="animate-pulse"><div className="aspect-[.82] rounded-sm bg-[#e9e1d3]" /><div className="mt-3 h-3 w-2/3 rounded bg-[#e9e1d3]" /><div className="mt-2 h-3 w-1/3 rounded bg-[#e9e1d3]" /></div>)}</div>; }
function QueryNotice({ onRetry }: { onRetry: () => void }) { return <div className="rounded border border-[#d9d0bf] bg-[#efe9dc] p-8 text-center"><p className="font-serif text-2xl">Belum dapat memuat data.</p><p className="mt-2 text-sm text-[#6f6b63]">Coba lagi sebentar. Kami sedang menyiapkan etalase untukmu.</p><button onClick={onRetry} className="mt-5 border border-[#1a1a1a] px-5 py-2 text-xs font-bold uppercase tracking-widest" data-testid="button-retry">Coba lagi</button></div>; }

function ProductCard({ product, onAdd }: { product: Product; onAdd: (product: Product) => void }) {
  const [liked, setLiked] = useState(false);
  return <article className="group" data-testid={`card-product-${product.id}`}><div className="relative aspect-[.84] overflow-hidden rounded-sm bg-[#e6ddcf]"><Link href={`/produk/${product.slug}`} data-testid={`link-product-${product.id}`}><img src={imageFor(product.image)} alt={product.name} className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-[1.04]" /></Link>{product.badge && <span className="absolute left-3 top-3 bg-[#f5f0e6] px-2.5 py-1 text-[9px] font-bold uppercase tracking-[.13em]">{product.badge}</span>}<button onClick={() => setLiked(!liked)} className={`absolute right-3 top-3 rounded-full p-2 transition-colors ${liked ? 'bg-[#c9a961] text-[#1a1a1a]' : 'bg-[#f5f0e6]/85'}`} data-testid={`button-wishlist-${product.id}`}><Heart size={15} fill={liked ? 'currentColor' : 'none'} /></button><button onClick={() => onAdd(product)} className="absolute bottom-3 left-3 right-3 translate-y-3 bg-[#1a1a1a] py-3 text-[10px] font-bold uppercase tracking-[.14em] text-[#f5f0e6] opacity-0 transition-all group-hover:translate-y-0 group-hover:opacity-100" data-testid={`button-add-product-${product.id}`}>Tambah ke tas</button></div><div className="mt-3"><p className="text-[10px] uppercase tracking-[.13em] text-[#9b958b]">{product.store} · {product.category}</p><Link href={`/produk/${product.slug}`} className="mt-1 block font-serif text-[17px] leading-tight hover:underline" data-testid={`link-product-name-${product.id}`}>{product.name}</Link><div className="mt-2 flex items-center justify-between"><span className="text-sm font-semibold">{rupiah(product.price)}</span><span className="text-[11px] text-[#777168]">★ {product.rating} <span className="text-[#a39d93]">({product.reviewCount})</span></span></div></div></article>;
}

function Home() {
  const productsQuery = useListProducts({ limit: 12 });
  const categoriesQuery = useListCategories();
  const storesQuery = useListStores();
  const [, setLocation] = useLocation();
  const [cartCount, setCartCount] = useState(0);
  const [subscribed, setSubscribed] = useState(false);
  const products = productsQuery.data?.length ? productsQuery.data : sampleProducts;
  const categories = categoriesQuery.data?.length ? categoriesQuery.data : sampleCategories;
  const stores = storesQuery.data?.length ? storesQuery.data : sampleStores;
  const add = (product: Product) => { const cart = JSON.parse(localStorage.getItem('lumea-cart') || '[]'); const next = [...cart, { product, qty: 1 }]; localStorage.setItem('lumea-cart', JSON.stringify(next)); setCartCount(next.length); };
  return <Shell><section className="relative overflow-hidden border-b border-[#d9d0bf]"><div className="mx-auto grid max-w-[1320px] items-end gap-10 px-5 pb-16 pt-16 sm:px-10 sm:pt-24 lg:grid-cols-[.88fr_1.12fr] lg:px-16 lg:pb-24"><div className="relative z-10"><p className="mb-6 text-[10px] font-bold uppercase tracking-[.28em] text-[#a3844b]">Kurasi Indonesia · Edisi 01</p><h1 className="max-w-xl font-serif text-[clamp(3.5rem,8vw,7.8rem)] leading-[.88] tracking-[-.04em]">Benda yang<br /><i className="text-[#a3844b]">punya cerita.</i></h1><p className="mt-8 max-w-sm text-sm leading-7 text-[#6f6b63]">Temukan barang sehari-hari yang dibuat dengan niat baik, oleh tangan-tangan yang dekat dengan rumah.</p><Link href="/produk" className="mt-8 inline-flex items-center gap-3 border-b border-[#1a1a1a] pb-2 text-xs font-bold uppercase tracking-[.16em]" data-testid="link-hero-discover">Jelajahi kurasi <ArrowRight size={15} /></Link></div><div className="relative"><div className="aspect-[1.22] overflow-hidden bg-[#d5c8b7]"><img src={imageFor(products[0]?.image)} alt="Koleksi Yumaera" className="h-full w-full object-cover" /></div><div className="absolute -bottom-5 -left-3 bg-[#c9a961] px-5 py-4 sm:-left-8"><p className="text-[9px] font-bold uppercase tracking-[.17em]">Benda baik</p><p className="mt-1 font-serif text-xl">untuk hidup yang nyata.</p></div><div className="absolute -right-2 -top-5 hidden h-28 w-28 rounded-full border border-[#c9a961] sm:block"><span className="flex h-full items-center justify-center text-center text-[9px] uppercase tracking-[.14em]">Made<br />with<br />care</span></div></div></div></section><section className="mx-auto max-w-[1320px] px-5 py-16 sm:px-10 lg:px-16"><div className="flex items-end justify-between"><div><p className="text-[10px] font-bold uppercase tracking-[.25em] text-[#a3844b]">Pilihan minggu ini</p><h2 className="mt-2 font-serif text-3xl sm:text-4xl">Yang sedang dibicarakan</h2></div><Link href="/produk" className="hidden items-center gap-2 text-xs font-bold uppercase tracking-[.13em] sm:flex" data-testid="link-view-all-products">Lihat semua <ChevronRight size={15} /></Link></div><div className="mt-9">{productsQuery.isLoading ? <LoadingGrid /> : productsQuery.isError ? <QueryNotice onRetry={() => productsQuery.refetch()} /> : <div className="grid grid-cols-2 gap-x-4 gap-y-10 md:grid-cols-3 lg:grid-cols-4">{products.slice(0, 8).map((p) => <ProductCard key={p.id} product={p} onAdd={add} />)}</div>}</div></section><section className="border-y border-[#d9d0bf] bg-[#efe9dc]"><div className="mx-auto grid max-w-[1320px] gap-12 px-5 py-16 sm:px-10 lg:grid-cols-[.7fr_1.3fr] lg:px-16 lg:py-20"><div><p className="text-[10px] font-bold uppercase tracking-[.25em] text-[#a3844b]">Jelajah berdasarkan rasa</p><h2 className="mt-3 font-serif text-4xl leading-tight">Mulai dari<br /><i>yang kamu butuhkan.</i></h2></div><div className="grid grid-cols-2 gap-3 sm:grid-cols-4">{categories.map((category, i) => <Link href={`/produk?category=${encodeURIComponent(category.name)}`} key={category.id} className="group flex min-h-36 flex-col justify-between border border-[#d5cbb9] p-4 transition-colors hover:bg-[#f5f0e6]" data-testid={`link-category-${category.id}`}><span className="text-3xl" style={{ color: category.accent }}>{category.icon}</span><div><p className="font-serif text-lg">{category.name}</p><p className="mt-1 text-[10px] uppercase tracking-[.12em] text-[#8b8479]">{category.itemCount} benda</p></div></Link>)}</div></div></section><section className="mx-auto max-w-[1320px] px-5 py-16 sm:px-10 lg:px-16"><div className="mb-8 flex items-end justify-between"><div><p className="text-[10px] font-bold uppercase tracking-[.25em] text-[#a3844b]">Toko pilihan</p><h2 className="mt-2 font-serif text-3xl">Ruang kecil, karya besar.</h2></div><Link href="/produk" className="text-xs font-bold uppercase tracking-[.13em]" data-testid="link-browse-stores">Telusuri toko</Link></div><div className="grid gap-4 md:grid-cols-3">{stores.map((store) => <div key={store.id} className="flex items-center gap-4 border-t border-[#d9d0bf] py-5" data-testid={`card-store-${store.id}`}><img src={imageFor(store.image)} alt={store.name} className="h-16 w-16 rounded-full object-cover" /><div className="min-w-0"><p className="font-serif text-xl">{store.name}</p><p className="mt-1 text-xs text-[#777168]">{store.handle} · {store.productCount} produk</p><p className="mt-2 text-[10px] font-bold uppercase tracking-[.12em] text-[#a3844b]">★ {store.rating} {store.verified && <span className="ml-2 text-[#777168]"><ShieldCheck size={13} className="inline" /> Terverifikasi</span>}</p></div></div>)}</div></section><section className="mx-auto mb-16 max-w-[1320px] px-5 sm:px-10 lg:px-16"><div className="grid gap-5 bg-[#1a1a1a] px-7 py-10 text-[#f5f0e6] sm:grid-cols-[1fr_auto] sm:items-center sm:px-12"><div><p className="text-[10px] font-bold uppercase tracking-[.25em] text-[#c9a961]">Jurnal Lumea</p><h2 className="mt-2 font-serif text-3xl">Hal baik, dikirim<br /><i>dengan cerita.</i></h2></div><button onClick={() => setSubscribed(true)} className="flex items-center gap-2 border-b border-[#c9a961] pb-2 text-left text-xs font-bold uppercase tracking-[.14em]" data-testid="button-subscribe">{subscribed ? <><Check size={15} /> Kamu sudah ikut</> : <>Ikuti cerita kami <ArrowRight size={15} /></>}</button></div></section>{cartCount > 0 && <button onClick={() => setLocation('/keranjang')} className="fixed bottom-20 right-5 z-30 flex items-center gap-3 bg-[#1a1a1a] px-5 py-3 text-xs font-bold uppercase tracking-widest text-[#f5f0e6] shadow-lg lg:bottom-8" data-testid="button-floating-cart"><ShoppingBag size={16} /> {cartCount} di tas</button>}</Shell>;
}

function Catalog() {
  const queryString = new URLSearchParams(window.location.search);
  const [search, setSearch] = useState(queryString.get('search') || '');
  const [category, setCategory] = useState(queryString.get('category') || '');
  const [sort, setSort] = useState('featured');
  const params = useMemo(() => ({ limit: 50, ...(search ? { search } : {}), ...(category ? { category } : {}) }), [search, category]);
  const query = useListProducts(params);
  const categoriesQuery = useListCategories();
  const products = (query.data === undefined ? sampleProducts : query.data).slice().sort((a, b) => sort === 'low' ? a.price - b.price : sort === 'high' ? b.price - a.price : 0);
  const add = (product: Product) => { const cart = JSON.parse(localStorage.getItem('lumea-cart') || '[]'); localStorage.setItem('lumea-cart', JSON.stringify([...cart, { product, qty: 1 }])); };
  return <Shell><div className="mx-auto max-w-[1320px] px-5 py-12 sm:px-10 lg:px-16 lg:py-16"><PageIntro eyebrow="Katalog Lumea" title="Pilih dengan pelan." detail="Barang yang baik tidak perlu terburu-buru. Jelajahi kurasi dari pembuat lokal terpilih." /><div className="mb-8 flex flex-col gap-4 border-y border-[#d9d0bf] py-4 md:flex-row md:items-center md:justify-between"><div className="flex gap-2 overflow-x-auto pb-1">{['', ...(categoriesQuery.data || sampleCategories).map((c) => c.name)].map((item) => <button key={item || 'all'} onClick={() => setCategory(item)} className={`whitespace-nowrap px-3 py-2 text-[10px] font-bold uppercase tracking-[.13em] ${category === item ? 'bg-[#1a1a1a] text-[#f5f0e6]' : 'border border-[#d9d0bf] text-[#6f6b63]'}`} data-testid={`button-filter-${item || 'all'}`}>{item || 'Semua benda'}</button>)}</div><div className="flex items-center gap-2"><Search size={16} className="text-[#938a7e]" /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Cari produk..." className="w-36 bg-transparent text-sm outline-none placeholder:text-[#9b958b] sm:w-52" data-testid="input-catalog-search" /><select value={sort} onChange={(e) => setSort(e.target.value)} className="border-l border-[#d9d0bf] bg-transparent pl-3 text-xs outline-none" data-testid="select-catalog-sort"><option value="featured">Unggulan</option><option value="low">Harga terendah</option><option value="high">Harga tertinggi</option></select></div></div>{query.isLoading ? <LoadingGrid /> : query.isError ? <QueryNotice onRetry={() => query.refetch()} /> : products.length === 0 ? <div className="py-24 text-center"><Sparkles className="mx-auto text-[#c9a961]" /><h2 className="mt-5 font-serif text-3xl">Belum ada yang cocok.</h2><p className="mt-2 text-sm text-[#6f6b63]">Coba kata kunci atau kategori lain.</p><button onClick={() => { setSearch(''); setCategory(''); }} className="mt-5 border-b border-[#1a1a1a] pb-1 text-xs font-bold uppercase tracking-widest" data-testid="button-clear-filter">Bersihkan filter</button></div> : <div className="grid grid-cols-2 gap-x-4 gap-y-10 md:grid-cols-3 lg:grid-cols-4">{products.map((p) => <ProductCard key={p.id} product={p} onAdd={add} />)}</div>}<p className="mt-14 text-center text-[10px] uppercase tracking-[.2em] text-[#9b958b]">{products.length} benda ditemukan</p></div></Shell>;
}

function ProductDetail() {
  const { slug = '' } = useParams<{ slug: string }>();
  const query = useGetProduct(slug, { query: { queryKey: getGetProductQueryKey(slug), enabled: !!slug } });
  const product = query.data || sampleProducts.find((p) => p.slug === slug) || sampleProducts[0];
  const [qty, setQty] = useState(1);
  const [added, setAdded] = useState(false);
  const [selectedColor, setSelectedColor] = useState(product.colors[0]);
  const add = () => { const cart = JSON.parse(localStorage.getItem('lumea-cart') || '[]'); localStorage.setItem('lumea-cart', JSON.stringify([...cart, { product, qty }])); setAdded(true); };
  if (query.isLoading) return <Shell><div className="mx-auto max-w-[1320px] px-5 py-16"><LoadingGrid /></div></Shell>;
  return <Shell><div className="mx-auto max-w-[1320px] px-5 py-10 sm:px-10 lg:px-16 lg:py-16"><Link href="/produk" className="mb-9 inline-flex items-center gap-2 text-[10px] font-bold uppercase tracking-[.18em] text-[#777168]" data-testid="link-back-catalog">← Kembali ke katalog</Link><div className="grid gap-10 lg:grid-cols-[1.05fr_.95fr] lg:gap-20"><div className="relative aspect-[.9] overflow-hidden bg-[#e6ddcf]"><img src={imageFor(product.image)} alt={product.name} className="h-full w-full object-cover" /><span className="absolute bottom-5 left-5 bg-[#f5f0e6] px-3 py-2 text-[10px] font-bold uppercase tracking-[.14em]">{product.store}</span></div><div className="flex flex-col justify-center"><p className="text-[10px] font-bold uppercase tracking-[.25em] text-[#a3844b]">{product.category} · {product.store}</p><h1 className="mt-4 max-w-xl font-serif text-4xl leading-tight sm:text-6xl">{product.name}</h1><div className="mt-5 flex items-center gap-3"><span className="text-sm font-semibold">{rupiah(product.price)}</span>{product.compareAtPrice && <del className="text-sm text-[#9b958b]">{rupiah(product.compareAtPrice)}</del>}<span className="ml-2 text-xs text-[#777168]">★ {product.rating} · {product.reviewCount} ulasan</span></div><p className="mt-7 max-w-md text-sm leading-7 text-[#6f6b63]">{product.description || 'Benda pilihan dari pembuat lokal Indonesia, dibuat untuk dipakai dan disayangi setiap hari.'}</p><div className="mt-8 border-t border-[#d9d0bf] pt-6"><p className="mb-3 text-[10px] font-bold uppercase tracking-[.16em]">Pilih warna · <span className="font-normal normal-case tracking-normal text-[#777168]">{selectedColor}</span></p><div className="flex gap-2">{product.colors.map((color) => <button key={color} onClick={() => setSelectedColor(color)} className={`h-7 w-7 rounded-full border-2 border-[#f5f0e6] ring-1 ${selectedColor === color ? 'ring-[#1a1a1a]' : 'ring-[#bbb1a2]'}`} style={{ background: color }} data-testid={`button-color-${color.slice(1)}`} />)}</div></div><div className="mt-8 flex gap-3"><div className="flex items-center border border-[#d9d0bf]"><button onClick={() => setQty(Math.max(1, qty - 1))} className="p-3" data-testid="button-qty-minus"><Minus size={15} /></button><span className="w-8 text-center text-sm">{qty}</span><button onClick={() => setQty(qty + 1)} className="p-3" data-testid="button-qty-plus"><Plus size={15} /></button></div><button onClick={add} className="flex flex-1 items-center justify-center gap-2 bg-[#1a1a1a] px-5 py-3 text-xs font-bold uppercase tracking-[.14em] text-[#f5f0e6] transition-colors hover:bg-[#c9a961] hover:text-[#1a1a1a]" data-testid="button-add-to-cart">{added ? <><Check size={16} /> Ditambahkan</> : <><ShoppingBag size={16} /> Tambah ke tas</>}</button></div><div className="mt-9 grid gap-3 border-t border-[#d9d0bf] pt-6 text-xs text-[#6f6b63]"><p className="flex items-center gap-3"><Truck size={16} className="text-[#a3844b]" /> Pengiriman aman ke seluruh Indonesia</p><p className="flex items-center gap-3"><ShieldCheck size={16} className="text-[#a3844b]" /> Karya asli, penjual terverifikasi</p></div></div></div></div></Shell>;
}

type CartItem = { product: Product; qty: number };
function useCart() {
  const [items, setItems] = useState<CartItem[]>(() => { try { return JSON.parse(localStorage.getItem('lumea-cart') || '[]'); } catch { return []; } });
  const sync = (next: CartItem[]) => { setItems(next); localStorage.setItem('lumea-cart', JSON.stringify(next)); };
  return { items, sync };
}
function Cart() {
  const { items, sync } = useCart();
  const [, setLocation] = useLocation();
  const total = items.reduce((sum, item) => sum + item.product.price * item.qty, 0);
  return <Shell><div className="mx-auto max-w-[1100px] px-5 py-12 sm:px-10 lg:py-16"><PageIntro eyebrow="Tas belanja" title="Barang yang kamu pilih." />{items.length === 0 ? <div className="border-y border-[#d9d0bf] py-20 text-center"><ShoppingBag className="mx-auto text-[#c9a961]" size={28} /><h2 className="mt-5 font-serif text-3xl">Tasmu masih kosong.</h2><p className="mt-2 text-sm text-[#6f6b63]">Ada banyak benda baik menunggu untuk ditemukan.</p><Link href="/produk" className="mt-6 inline-block border-b border-[#1a1a1a] pb-1 text-xs font-bold uppercase tracking-[.16em]" data-testid="link-empty-cart">Lihat katalog</Link></div> : <div className="grid gap-10 lg:grid-cols-[1fr_330px]"><div className="divide-y divide-[#d9d0bf] border-y border-[#d9d0bf]">{items.map((item, i) => <div key={`${item.product.id}-${i}`} className="flex gap-4 py-5" data-testid={`row-cart-${item.product.id}-${i}`}><img src={imageFor(item.product.image)} alt={item.product.name} className="h-28 w-24 object-cover" /><div className="flex min-w-0 flex-1 flex-col"><p className="text-[10px] uppercase tracking-[.12em] text-[#9b958b]">{item.product.store}</p><Link href={`/produk/${item.product.slug}`} className="mt-1 font-serif text-xl" data-testid={`link-cart-product-${item.product.id}`}>{item.product.name}</Link><div className="mt-auto flex items-center justify-between gap-2"><div className="flex items-center border border-[#d9d0bf]"><button onClick={() => sync(items.map((x, j) => j === i ? { ...x, qty: Math.max(1, x.qty - 1) } : x))} className="p-1.5" data-testid={`button-cart-minus-${item.product.id}`}><Minus size={13} /></button><span className="w-7 text-center text-xs">{item.qty}</span><button onClick={() => sync(items.map((x, j) => j === i ? { ...x, qty: x.qty + 1 } : x))} className="p-1.5" data-testid={`button-cart-plus-${item.product.id}`}><Plus size={13} /></button></div><span className="text-sm font-semibold">{rupiah(item.product.price * item.qty)}</span></div></div><button onClick={() => sync(items.filter((_, j) => j !== i))} className="self-start p-1 text-[#8e867b]" data-testid={`button-remove-cart-${item.product.id}`}><X size={17} /></button></div>)}</div><div className="h-fit bg-[#efe9dc] p-6"><p className="text-[10px] font-bold uppercase tracking-[.2em] text-[#8e867b]">Ringkasan pesanan</p><div className="mt-6 flex justify-between text-sm"><span>Subtotal</span><span>{rupiah(total)}</span></div><div className="mt-3 flex justify-between text-sm text-[#6f6b63]"><span>Pengiriman</span><span>Gratis</span></div><div className="my-6 border-t border-[#d9d0bf]" /><div className="flex justify-between font-serif text-2xl"><span>Total</span><span>{rupiah(total)}</span></div><button onClick={() => setLocation('/checkout')} className="mt-7 flex w-full items-center justify-center gap-2 bg-[#1a1a1a] py-4 text-xs font-bold uppercase tracking-[.15em] text-[#f5f0e6]" data-testid="button-proceed-checkout">Lanjut ke pembayaran <ArrowRight size={15} /></button></div></div>}</div></Shell>;
}

function Checkout() {
  const { items, sync } = useCart();
  const [, setLocation] = useLocation();
  const create = useCreateOrder();
  const [payment, setPayment] = useState('transfer_bank');
  const item = items[0];
  const submit = () => { if (!item) return; create.mutate({ data: { productId: item.product.id, qty: item.qty, paymentMethod: payment } }, { onSuccess: (order) => { sync([]); setLocation(`/pesanan/${order.id}`); } }); };
  if (!item) return <Shell><div className="mx-auto max-w-[900px] px-5 py-20 text-center"><PageIntro eyebrow="Pembayaran" title="Tasmu masih kosong." /><Link href="/produk" className="border-b border-[#1a1a1a] pb-1 text-xs font-bold uppercase tracking-widest" data-testid="link-checkout-empty">Kembali belanja</Link></div></Shell>;
  return <Shell><div className="mx-auto max-w-[1100px] px-5 py-12 sm:px-10 lg:py-16"><PageIntro eyebrow="Satu langkah lagi" title="Konfirmasi pesanan." /><div className="grid gap-10 lg:grid-cols-[1fr_350px]"><div><section className="border-y border-[#d9d0bf] py-6"><h2 className="font-serif text-2xl">Alamat pengiriman</h2><div className="mt-5 grid gap-4 sm:grid-cols-2"><input className="border-b border-[#bdb5a6] bg-transparent px-1 py-3 text-sm outline-none" placeholder="Nama lengkap" data-testid="input-checkout-name" /><input className="border-b border-[#bdb5a6] bg-transparent px-1 py-3 text-sm outline-none" placeholder="Nomor telepon" data-testid="input-checkout-phone" /><input className="border-b border-[#bdb5a6] bg-transparent px-1 py-3 text-sm outline-none sm:col-span-2" placeholder="Alamat lengkap" data-testid="input-checkout-address" /></div></section><section className="py-7"><h2 className="font-serif text-2xl">Metode pembayaran</h2><div className="mt-5 grid gap-3"><label className={`flex cursor-pointer items-center justify-between border p-4 ${payment === 'transfer_bank' ? 'border-[#c9a961] bg-[#efe9dc]' : 'border-[#d9d0bf]'}`}><span className="flex items-center gap-3 text-sm"><WalletCards size={19} /> Transfer bank</span><input type="radio" checked={payment === 'transfer_bank'} onChange={() => setPayment('transfer_bank')} data-testid="radio-payment-bank" /></label><label className={`flex cursor-pointer items-center justify-between border p-4 ${payment === 'e_wallet' ? 'border-[#c9a961] bg-[#efe9dc]' : 'border-[#d9d0bf]'}`}><span className="flex items-center gap-3 text-sm"><WalletCards size={19} /> E-wallet</span><input type="radio" checked={payment === 'e_wallet'} onChange={() => setPayment('e_wallet')} data-testid="radio-payment-wallet" /></label></div></section></div><div className="h-fit bg-[#efe9dc] p-6"><p className="text-[10px] font-bold uppercase tracking-[.2em] text-[#8e867b]">Pesananmu</p><div className="mt-5 flex gap-3"><img src={imageFor(item.product.image)} alt={item.product.name} className="h-20 w-16 object-cover" /><div><p className="font-serif text-lg leading-tight">{item.product.name}</p><p className="mt-1 text-xs text-[#6f6b63]">{item.qty} × {rupiah(item.product.price)}</p></div></div><div className="my-5 border-t border-[#d9d0bf]" /><div className="flex justify-between font-serif text-2xl"><span>Total</span><span>{rupiah(item.product.price * item.qty)}</span></div><button onClick={submit} disabled={create.isPending} className="mt-7 w-full bg-[#1a1a1a] py-4 text-xs font-bold uppercase tracking-[.15em] text-[#f5f0e6] disabled:opacity-50" data-testid="button-confirm-order">{create.isPending ? 'Memproses...' : 'Buat pesanan'}</button><p className="mt-4 text-center text-[10px] leading-5 text-[#8e867b]">Dengan menekan tombol ini, kamu menyetujui syarat pembelian Lumea.</p></div></div></div></Shell>;
}

function StatusBadge({ order }: { order: Order }) {
  const tone = order.statusTone || order.status;
  const colors = tone.includes('success') || tone === 'selesai' || tone === 'diterima' ? 'bg-[#dce7da] text-[#416247]' : tone.includes('warning') || tone.includes('pending') || tone === 'diproses' ? 'bg-[#f0e2bd] text-[#856b31]' : tone.includes('danger') || tone === 'dibatalkan' ? 'bg-[#ecd7d1] text-[#914e43]' : 'bg-[#dce3e6] text-[#53666d]';
  return <span className={`inline-flex px-2.5 py-1 text-[9px] font-bold uppercase tracking-[.13em] ${colors}`} data-testid={`status-order-${order.id}`}>{order.statusLabel || order.status}</span>;
}
function Orders() {
  const query = useListOrders({ query: { queryKey: getListOrdersQueryKey() } });
  const orders = query.data || [];
  return <Shell><div className="mx-auto max-w-[1050px] px-5 py-12 sm:px-10 lg:py-16"><PageIntro eyebrow="Riwayat belanja" title="Pesananmu, selalu terpantau." detail="Dari pembayaran sampai tiba di depan pintu, kami catat semuanya." />{query.isLoading ? <LoadingGrid /> : query.isError ? <QueryNotice onRetry={() => query.refetch()} /> : orders.length === 0 ? <div className="border-y border-[#d9d0bf] py-20 text-center"><Package className="mx-auto text-[#c9a961]" /><h2 className="mt-4 font-serif text-3xl">Belum ada pesanan.</h2><p className="mt-2 text-sm text-[#6f6b63]">Pesanan pertama biasanya dimulai dari satu benda kecil.</p><Link href="/produk" className="mt-5 inline-block border-b border-[#1a1a1a] pb-1 text-xs font-bold uppercase tracking-widest" data-testid="link-order-empty">Mulai mencari</Link></div> : <div className="divide-y divide-[#d9d0bf] border-y border-[#d9d0bf]">{orders.map((order) => <Link href={`/pesanan/${order.id}`} key={order.id} className="group grid gap-4 py-6 sm:grid-cols-[1fr_auto_auto] sm:items-center" data-testid={`link-order-${order.id}`}><div><div className="flex flex-wrap items-center gap-3"><p className="font-serif text-xl">{order.store}</p><StatusBadge order={order} /></div><p className="mt-2 text-xs text-[#777168]">#{order.invoiceNo} · {shortDate(order.createdAt)}</p></div><div className="flex items-center gap-6"><div className="hidden text-right sm:block"><p className="text-[10px] uppercase tracking-[.13em] text-[#9b958b]">Total</p><p className="mt-1 text-sm font-semibold">{rupiah(order.total)}</p></div><ChevronRight size={18} className="text-[#a3844b] transition-transform group-hover:translate-x-1" /></div></Link>)}</div>}</div></Shell>;
}

function OrderDetail() {
  const { id = '' } = useParams<{ id: string }>();
  const query = useGetOrder(id, { query: { queryKey: getGetOrderQueryKey(id), enabled: !!id } });
  const fallback = (query.data || null) as Order | null;
  return <Shell><div className="mx-auto max-w-[1100px] px-5 py-12 sm:px-10 lg:py-16">{query.isLoading ? <LoadingGrid /> : query.isError ? <QueryNotice onRetry={() => query.refetch()} /> : !fallback ? <div className="py-20 text-center"><PageIntro eyebrow="Pesanan" title="Pesanan tidak ditemukan." /></div> : <><div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><Link href="/pesanan" className="mb-6 inline-flex text-[10px] font-bold uppercase tracking-widest text-[#777168]" data-testid="link-back-orders">← Semua pesanan</Link><p className="text-[10px] font-bold uppercase tracking-[.2em] text-[#a3844b]">Detail pesanan</p><h1 className="mt-2 font-serif text-4xl">{fallback.store}</h1><p className="mt-2 text-sm text-[#777168]">#{fallback.invoiceNo} · {shortDate(fallback.createdAt)}</p></div><div className="flex items-center gap-3"><StatusBadge order={fallback} /><button onClick={() => window.print()} className="flex items-center gap-2 border border-[#d9d0bf] px-3 py-2 text-[10px] font-bold uppercase tracking-widest" data-testid="button-print-invoice"><Printer size={14} /> Cetak invoice</button></div></div><div className="mt-12 grid gap-10 lg:grid-cols-[1fr_320px]"><div><div className="border-y border-[#d9d0bf] py-8"><h2 className="font-serif text-2xl">Perjalanan pesanan</h2><div className="mt-8">{fallback.tracking?.map((event, i) => <div key={`${event.label}-${i}`} className="relative flex gap-4 pb-7 last:pb-0"><div className="relative flex w-6 justify-center">{i < (fallback.tracking?.length || 1) - 1 && <span className={`absolute top-5 h-full w-px ${event.completed ? 'bg-[#c9a961]' : 'bg-[#d9d0bf]'}`} />}<span className={`relative z-10 flex h-5 w-5 items-center justify-center rounded-full border ${event.completed || event.active ? 'border-[#c9a961] bg-[#c9a961]' : 'border-[#cfc5b6] bg-[#f5f0e6]'}`}>{event.completed && <Check size={12} />}</span></div><div><p className={`text-sm ${event.active ? 'font-semibold' : ''}`}>{event.label}</p><p className="mt-1 text-xs text-[#8e867b]">{shortDate(event.timestamp)}</p></div></div>)}</div></div><div className="mt-8"><h2 className="font-serif text-2xl">Isi paket</h2><div className="mt-5 divide-y divide-[#d9d0bf] border-y border-[#d9d0bf]">{fallback.items?.map((item) => <div className="flex gap-4 py-4" key={item.id} data-testid={`row-order-item-${item.id}`}><img src={imageFor(item.image)} alt={item.name} className="h-16 w-14 object-cover" /><div className="flex-1"><p className="font-serif text-lg">{item.name}</p><p className="mt-1 text-xs text-[#777168]">{item.qty} × {rupiah(item.price)}</p></div><p className="text-sm font-semibold">{rupiah(item.qty * item.price)}</p></div>)}</div></div></div><aside className="h-fit bg-[#efe9dc] p-6"><p className="text-[10px] font-bold uppercase tracking-[.2em] text-[#8e867b]">Ringkasan</p><div className="mt-6 flex justify-between text-sm"><span>Total pesanan</span><strong>{rupiah(fallback.total)}</strong></div><div className="mt-5 border-t border-[#d9d0bf] pt-5"><p className="text-xs text-[#777168]">Estimasi tiba</p><p className="mt-1 font-serif text-xl">{fallback.eta || 'Segera'}</p></div>{fallback.trackingNo && <div className="mt-5 border-t border-[#d9d0bf] pt-5"><p className="text-xs text-[#777168]">Nomor resi</p><p className="mt-1 text-sm font-semibold">{fallback.trackingNo}</p></div>}</aside></div></>}</div></Shell>;
}

function Notifications() {
  const query = useListNotifications({ query: { queryKey: getListNotificationsQueryKey() } });
  const mark = useMarkNotificationRead();
  const queryClient = useQueryClient();
  const notifications = query.data || [];
  const read = (item: Notification) => { if (!item.isRead) mark.mutate({ id: item.id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListNotificationsQueryKey() }) }); };
  return <Shell><div className="mx-auto max-w-[900px] px-5 py-12 sm:px-10 lg:py-16"><PageIntro eyebrow="Pusat kabar" title="Notifikasi." detail="Catatan kecil tentang pesanan, toko, dan hal-hal yang mungkin kamu sukai." />{query.isLoading ? <LoadingGrid /> : notifications.length === 0 ? <div className="border-y border-[#d9d0bf] py-20 text-center"><Bell className="mx-auto text-[#c9a961]" /><h2 className="mt-4 font-serif text-3xl">Semuanya tenang.</h2><p className="mt-2 text-sm text-[#6f6b63]">Belum ada kabar baru hari ini.</p></div> : <div className="divide-y divide-[#d9d0bf] border-y border-[#d9d0bf]">{notifications.map((item) => <button onClick={() => read(item)} key={item.id} className={`flex w-full gap-4 py-5 text-left ${!item.isRead ? 'bg-[#efe9dc]' : ''}`} data-testid={`button-notification-${item.id}`}><span className={`mt-1 flex h-9 w-9 shrink-0 items-center justify-center rounded-full ${item.isRead ? 'bg-[#e9e1d3]' : 'bg-[#c9a961]'}`}><Bell size={16} /></span><span className="flex-1"><strong className="font-serif text-lg font-medium">{item.title}</strong><span className="mt-1 block text-sm leading-6 text-[#6f6b63]">{item.message}</span><span className="mt-2 block text-[10px] uppercase tracking-[.14em] text-[#9b958b]">{shortDate(item.createdAt)}</span></span>{!item.isRead && <span className="mt-3 h-2 w-2 rounded-full bg-[#b67554]" />}</button>)}</div>}</div></Shell>;
}

function Seller() {
  const query = useGetDashboardSummary({ query: { queryKey: getGetDashboardSummaryQueryKey() } });
  const [, setLocation] = useLocation();
  const summary: DashboardSummary = query.data || { revenue: 12840000, revenueDelta: 12.4, orders: 86, ordersDelta: 8.2, products: 42, lowStock: 6, weeklySales: [{ day: 'Sen', value: 2.4 }, { day: 'Sel', value: 3.1 }, { day: 'Rab', value: 1.9 }, { day: 'Kam', value: 4.2 }, { day: 'Jum', value: 3.6 }, { day: 'Sab', value: 5.1 }, { day: 'Min', value: 4.6 }], recentOrders: [] };
  const max = Math.max(...summary.weeklySales.map((item) => item.value), 1);
  return <Shell><div className="mx-auto max-w-[1320px] px-5 py-12 sm:px-10 lg:px-16 lg:py-16"><div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><PageIntro eyebrow="Studio penjual · Karsa Studio" title="Selamat pagi, Rani." detail="Ini yang terjadi di tokomu minggu ini." /><button onClick={() => window.print()} className="mb-9 flex items-center justify-center gap-2 border border-[#d9d0bf] px-4 py-3 text-[10px] font-bold uppercase tracking-[.15em]" data-testid="button-seller-export"><Send size={14} /> Ekspor laporan</button></div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><div className="bg-[#1a1a1a] p-5 text-[#f5f0e6]"><p className="text-[10px] uppercase tracking-[.17em] text-[#c9a961]">Pendapatan</p><p className="mt-4 font-serif text-3xl">{rupiah(summary.revenue)}</p><p className="mt-2 text-xs text-[#c9a961]">↑ {summary.revenueDelta}% dari minggu lalu</p></div><div className="border border-[#d9d0bf] p-5"><p className="text-[10px] uppercase tracking-[.17em] text-[#8e867b]">Pesanan</p><p className="mt-4 font-serif text-3xl">{summary.orders}</p><p className="mt-2 text-xs text-[#477451]">↑ {summary.ordersDelta}% dari minggu lalu</p></div><div className="border border-[#d9d0bf] p-5"><p className="text-[10px] uppercase tracking-[.17em] text-[#8e867b]">Produk aktif</p><p className="mt-4 font-serif text-3xl">{summary.products}</p><p className="mt-2 text-xs text-[#777168]">Koleksi yang tampil</p></div><div className="border border-[#d9d0bf] p-5"><p className="text-[10px] uppercase tracking-[.17em] text-[#8e867b]">Stok menipis</p><p className="mt-4 font-serif text-3xl">{summary.lowStock}</p><p className="mt-2 text-xs text-[#914e43]">Perlu perhatian</p></div></div><div className="mt-8 grid gap-8 lg:grid-cols-[1.2fr_.8fr]"><section className="border border-[#d9d0bf] p-6"><div className="flex items-center justify-between"><div><p className="text-[10px] font-bold uppercase tracking-[.2em] text-[#a3844b]">Performa minggu ini</p><h2 className="mt-2 font-serif text-2xl">Penjualan harian</h2></div><span className="text-xs text-[#777168]">Dalam juta rupiah</span></div><div className="mt-10 flex h-48 items-end gap-2 sm:gap-4">{summary.weeklySales.map((item) => <div key={item.day} className="flex h-full flex-1 flex-col items-center justify-end gap-2"><div className="w-full max-w-10 bg-[#c9a961] transition-all hover:bg-[#1a1a1a]" style={{ height: `${(item.value / max) * 100}%` }} data-testid={`bar-sales-${item.day}`} /><span className="text-[10px] uppercase text-[#8e867b]">{item.day}</span></div>)}</div></section><section className="border border-[#d9d0bf] p-6"><p className="text-[10px] font-bold uppercase tracking-[.2em] text-[#a3844b]">Aksi cepat</p><h2 className="mt-2 font-serif text-2xl">Kelola tokomu</h2><div className="mt-7 grid gap-3"><button onClick={() => setLocation('/produk')} className="flex items-center justify-between border-b border-[#d9d0bf] py-3 text-sm" data-testid="button-manage-products">Kelola produk <ChevronRight size={16} /></button><button onClick={() => setLocation('/pesanan')} className="flex items-center justify-between border-b border-[#d9d0bf] py-3 text-sm" data-testid="button-manage-orders">Lihat pesanan masuk <ChevronRight size={16} /></button><button onClick={() => setLocation('/login')} className="flex items-center justify-between border-b border-[#d9d0bf] py-3 text-sm" data-testid="button-store-settings">Pengaturan toko <ChevronRight size={16} /></button></div></section></div><section className="mt-8 border-y border-[#d9d0bf]"><div className="flex items-center justify-between py-5"><h2 className="font-serif text-2xl">Pesanan terbaru</h2><Link href="/pesanan" className="text-[10px] font-bold uppercase tracking-[.15em]" data-testid="link-seller-orders">Lihat semua</Link></div>{summary.recentOrders.length ? summary.recentOrders.map((order) => <div key={order.id} className="flex justify-between border-t border-[#d9d0bf] py-4"><span>{order.invoiceNo}</span><StatusBadge order={order} /><strong>{rupiah(order.total)}</strong></div>) : <p className="border-t border-[#d9d0bf] py-8 text-sm text-[#777168]">Pesanan terbaru akan muncul di sini.</p>}</section></div></Shell>;
}

function Admin() {
  const summaryQuery = useGetDashboardSummary({ query: { queryKey: getGetDashboardSummaryQueryKey() } });
  const ordersQuery = useListOrders({ query: { queryKey: getListOrdersQueryKey() } });
  const productsQuery = useListProducts({ limit: 50 });
  const update = useUpdateOrderStatus();
  const queryClient = useQueryClient();
  const summary = summaryQuery.data;
  const orders = ordersQuery.data || [];
  const setPacking = (order: Order) => update.mutate({ id: order.id, data: { status: 'packing' } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getListOrdersQueryKey() }); queryClient.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() }); } });
  return <Shell><div className="mx-auto max-w-[1250px] px-5 py-12 sm:px-10 lg:px-16 lg:py-16"><PageIntro eyebrow="Lumea control room" title="Semua bergerak baik." detail="Ringkasan marketplace, toko, dan pesanan dalam satu pandangan." /><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><div className="bg-[#1a1a1a] p-5 text-[#f5f0e6]"><p className="text-[10px] uppercase tracking-widest text-[#c9a961]">GMV minggu ini</p><p className="mt-4 font-serif text-3xl">{rupiah(summary?.revenue || 0)}</p></div><div className="border border-[#d9d0bf] p-5"><p className="text-[10px] uppercase tracking-widest text-[#8e867b]">Pesanan</p><p className="mt-4 font-serif text-3xl">{summary?.orders || orders.length}</p></div><div className="border border-[#d9d0bf] p-5"><p className="text-[10px] uppercase tracking-widest text-[#8e867b]">Produk</p><p className="mt-4 font-serif text-3xl">{summary?.products || productsQuery.data?.length || 0}</p></div><div className="border border-[#d9d0bf] p-5"><p className="text-[10px] uppercase tracking-widest text-[#8e867b]">Perlu diproses</p><p className="mt-4 font-serif text-3xl">{orders.filter((o) => o.status === 'diproses').length}</p></div></div><div className="mt-8 border border-[#d9d0bf]"><div className="flex items-center justify-between border-b border-[#d9d0bf] p-5"><h2 className="font-serif text-2xl">Pesanan yang masuk</h2><span className="text-xs text-[#777168]">Admin view</span></div><div className="overflow-x-auto"><table className="w-full min-w-[650px] text-left text-sm"><thead className="bg-[#efe9dc] text-[10px] uppercase tracking-[.15em] text-[#8e867b]"><tr><th className="p-4 font-medium">Invoice</th><th className="p-4 font-medium">Toko</th><th className="p-4 font-medium">Tanggal</th><th className="p-4 font-medium">Status</th><th className="p-4 font-medium">Total</th><th className="p-4 font-medium" /></tr></thead><tbody>{orders.map((order) => <tr key={order.id} className="border-t border-[#d9d0bf]" data-testid={`row-admin-order-${order.id}`}><td className="p-4 font-semibold">{order.invoiceNo}</td><td className="p-4">{order.store}</td><td className="p-4 text-[#777168]">{shortDate(order.createdAt)}</td><td className="p-4"><StatusBadge order={order} /></td><td className="p-4 font-semibold">{rupiah(order.total)}</td><td className="p-4 text-right">{order.status === 'diproses' && <button onClick={() => setPacking(order)} disabled={update.isPending} className="text-[10px] font-bold uppercase tracking-[.12em] text-[#a3844b]" data-testid={`button-pack-order-${order.id}`}>Tandai packing</button>}</td></tr>)}{!orders.length && <tr><td colSpan={6} className="p-12 text-center text-sm text-[#777168]">Belum ada pesanan untuk ditampilkan.</td></tr>}</tbody></table></div></div></div></Shell>;
}

function Auth({ register = false }: { register?: boolean }) {
  const [, setLocation] = useLocation();
  return <div className="grid min-h-[100dvh] lg:grid-cols-2"><div className="hidden bg-[#1a1a1a] p-12 text-[#f5f0e6] lg:flex lg:flex-col lg:justify-between"><Logo /><div><p className="mb-5 text-[10px] font-bold uppercase tracking-[.25em] text-[#c9a961]">Ruang untuk benda baik</p><h1 className="max-w-md font-serif text-6xl leading-[.95]">Belanja yang terasa lebih dekat.</h1><p className="mt-7 max-w-sm text-sm leading-7 text-[#bcb5aa]">Lumea menghubungkanmu dengan pembuat lokal yang membuat barang sehari-hari dengan perhatian.</p></div><p className="text-xs text-[#8e867b]">LUMEA / INDONESIA, 2024</p></div><div className="flex flex-col p-6 sm:p-12"><div className="flex items-center justify-between lg:justify-end"><div className="lg:hidden"><Logo /></div><Link href="/" className="text-[10px] font-bold uppercase tracking-[.16em] text-[#777168]" data-testid="link-auth-home">Kembali ke beranda</Link></div><div className="m-auto w-full max-w-md py-12"><p className="text-[10px] font-bold uppercase tracking-[.25em] text-[#a3844b]">{register ? 'Buat akun baru' : 'Selamat datang kembali'}</p><h1 className="mt-3 font-serif text-4xl">{register ? 'Mulai perjalananmu.' : 'Masuk ke Lumea.'}</h1><p className="mt-3 text-sm leading-6 text-[#6f6b63]">{register ? 'Simpan benda favorit dan lacak setiap pesanan dengan mudah.' : 'Lanjutkan menemukan barang-barang yang dibuat dengan baik.'}</p><div className="mt-9 grid gap-5">{register && <input className="border-b border-[#bdb5a6] bg-transparent px-1 py-3 text-sm outline-none" placeholder="Nama lengkap" data-testid="input-register-name" />}<input type="email" className="border-b border-[#bdb5a6] bg-transparent px-1 py-3 text-sm outline-none" placeholder="Email" data-testid={register ? 'input-register-email' : 'input-login-email'} /><input type="password" className="border-b border-[#bdb5a6] bg-transparent px-1 py-3 text-sm outline-none" placeholder="Kata sandi" data-testid={register ? 'input-register-password' : 'input-login-password'} /><button onClick={() => setLocation('/')} className="mt-3 bg-[#1a1a1a] py-4 text-xs font-bold uppercase tracking-[.16em] text-[#f5f0e6]" data-testid={register ? 'button-register' : 'button-login'}>{register ? 'Buat akun' : 'Masuk'}</button></div><p className="mt-7 text-center text-sm text-[#777168]">{register ? 'Sudah punya akun?' : 'Belum punya akun?'} <Link href={register ? '/login' : '/register'} className="font-semibold text-[#1a1a1a] underline" data-testid="link-auth-switch">{register ? 'Masuk' : 'Daftar sekarang'}</Link></p></div></div></div>;
}

function Router() {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}><Switch><Route path="/" component={Home} /><Route path="/produk" component={Catalog} /><Route path="/produk/:slug" component={ProductDetail} /><Route path="/keranjang" component={Cart} /><Route path="/checkout" component={Checkout} /><Route path="/pesanan" component={Orders} /><Route path="/pesanan/:id" component={OrderDetail} /><Route path="/notifikasi" component={Notifications} /><Route path="/seller" component={Seller} /><Route path="/admin" component={Admin} /><Route path="/login" component={() => <Auth />} /><Route path="/register" component={() => <Auth register />} /><Route component={() => <Shell><div className="mx-auto max-w-3xl px-5 py-28 text-center"><PageIntro eyebrow="404" title="Halaman ini belum ada." /><Link href="/" className="border-b border-[#1a1a1a] pb-1 text-xs font-bold uppercase tracking-widest" data-testid="link-not-found-home">Kembali</Link></div></Shell>} /></Switch></ErrorBoundary>;
}

export default function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}